#pragma once

// Authenticated, distributed Boolean GMW for pre-challenge computation.
// Random bits/triples are generated by real malicious COT + checked aAND
// bucketing, not supplied by the free edaBit oracle. Only edaBits and keygen
// inputs may enter externally. Shares have WRK's explicit-bit representation.
// The upstream COT/aAND profile fixes two Delta bits: 126-bit key entropy,
// with the separately configured statistical parameter (default 64 bits).
#include "emp-ag/wrk.h"
#include "emp-ag/backend/preproc/triple_pool.h"
#include "emp-ag/backend/crypto/auth_open.h"
#include "emp-ag/backend/preproc/fkos_triples.h"
#include <algorithm>
#include <cstdint>
#include <memory>
#include <string>
#include <vector>

namespace emp::gmw {

#ifndef EMP_AG_GMW_TRIPLE_BATCH_SIZE
#define EMP_AG_GMW_TRIPLE_BATCH_SIZE 8192
#endif

template<int N> class Gmw {
 public:
  using Share = wrk::AuthShare<N>;
  using Shares = wrk::AuthShareVec<N>;
  static constexpr int authentication_key_entropy = 126;
  static constexpr size_t triple_chunk_size = EMP_AG_GMW_TRIPLE_BATCH_SIZE;
  static_assert(triple_chunk_size >= 128 && triple_chunk_size <= 1000000);
  const int party;
  const block Delta, session;
  const int statistical_security;
  const ag::TripleBackend triple_backend;
  uint64_t random_bits_generated = 0, triples_generated = 0;
  uint64_t ands_evaluated = 0, opening_batches = 0, last_and_depth = 0;

  Gmw(NetIOMP<N> *io, ThreadPool *pool, int party_in, block session_in,
      block Delta_in, int ssp = 64,
      ag::TripleBackend backend = ag::configured_triple_backend)
      : party(party_in), Delta(Delta_in), session(session_in),
        statistical_security(ssp), triple_backend(backend), io_(io), pool_(pool),
        triples_(io, pool, party_in, ssp, nullptr, session_in,
                 BaseOtKind::CSW, -1, -1, &Delta_in) {
    wrk::require(cmpBlock(&Delta, &triples_.Delta, 1),
                 "GMW preprocessing Delta mismatch");
    wrk::require(backend == ag::TripleBackend::HalfGate || backend == ag::TripleBackend::FKOS,
                 "unknown GMW triple backend");
    if (backend == ag::TripleBackend::FKOS)
      fkos_ = std::make_unique<ag::FkosTriples<N>>(io, pool, party, session, triples_.abit, ssp);
  }
  Gmw(const Gmw &) = delete;
  Gmw &operator=(const Gmw &) = delete;

  Share public_bit(bool value) const {
    active();
    Share out{};
    if (value) {
      if (party == 1) out.bit = 1;
      else out.key(wrk::peer_slot(party, 1)) = Delta;
    }
    return out;
  }

  Shares random(size_t count) {
    active();
    Shares result; result.reserve(count);
    while (result.size() < count) {
      const size_t length = std::min<size_t>(count - result.size(), 8192);
      ag::AShareBundleVec<N> native;
      triples_.abit.draw(static_cast<int>(length), native);
      for (const auto &s : native) result.push_back(export_share(s));
      random_bits_generated += length;
    }
    triples_.abit.maybe_flush_cot_check();
    return result;
  }

  std::vector<uint8_t> open(const Shares &values, const std::string &domain) {
    active();
    triples_.abit.maybe_flush_cot_check();
    std::vector<uint8_t> bits; bits.reserve(values.size());
    for (const auto &s : values) {
      wrk::require(s.bit <= 1, "GMW opening input is not a bit");
      bits.push_back(s.bit);
    }
    try {
      return ag::checked_open_bits(io_, pool_, party, Delta, session, domain,
          opening_batches++, bits,
          [&](int peer, size_t j) { return values[j].mac(wrk::peer_slot(party, peer)); },
          [&](int peer, size_t j) { return values[j].key(wrk::peer_slot(party, peer)); });
    } catch (...) { failed_ = true; throw; }
  }

  // Reserve a bank once before a circuit pass; the large COT/triple protocol
  // never runs per AND depth. Bank generation is memory-bounded in chunks;
  // the retained bank has three authenticated bits per future AND.
  void reserve_triples(size_t count) {
    active();
    if (bank_pos_ == bank_.size()) { bank_.clear(); bank_pos_ = 0; }
    while (bank_.size() - bank_pos_ < count) {
      const size_t length = std::min(count - (bank_.size() - bank_pos_), triple_chunk_size);
      // Amortize bucketing for a one-gate caller; retain extra triples
      // for subsequent AND batches rather than minting a tiny population.
      try { mint_triples(static_cast<int>(std::max<size_t>(128, length))); }
      catch (...) { failed_ = true; throw; }
    }
  }

  Shares and_batch(const Shares &left, const Shares &right) {
    active();
    wrk::require(left.size() == right.size(), "GMW AND batch shape mismatch");
    const size_t count = left.size();
    if (!count) return {};
    reserve_triples(count);
    Shares differences; differences.reserve(2 * count);
    for (size_t j = 0; j < count; ++j)
      differences.push_back(wrk::xor_share(left[j], bank_[bank_pos_ + j].a));
    for (size_t j = 0; j < count; ++j)
      differences.push_back(wrk::xor_share(right[j], bank_[bank_pos_ + j].b));
    const auto opened = open(differences, "GMW-Beaver-d-e");
    Shares out(count);
    for (size_t j = 0; j < count; ++j) {
      const auto &t = bank_[bank_pos_ + j];
      out[j] = t.c;
      if (opened[j]) out[j] = wrk::xor_share(out[j], t.b);
      if (opened[count + j]) out[j] = wrk::xor_share(out[j], t.a);
      if (opened[j] && opened[count + j])
        out[j] = wrk::xor_share(out[j], public_bit(true));
    }
    bank_pos_ += count; ands_evaluated += count;
    return out;
  }

  Shares evaluate(const circuit::BooleanProgram &program, const Shares &inputs) {
    active();
    circuit::validate_program(program);
    wrk::require(program.wire_reuse == circuit::WireReuse::None &&
        inputs.size() == program.num_inputs, "GMW requires dense circuit and exact inputs");
    const size_t count = wrk::count_gc_ands(program);
    reserve_triples(count);
    std::vector<uint32_t> depth(program.num_wires, 0);
    uint32_t max_depth = 0;
    for (const auto &g : program.gates) {
      using circuit::Op;
      uint32_t d = 0;
      if (g.op == Op::And || g.op == Op::Xor) d = std::max(depth[g.in0], depth[g.in1]);
      else if (g.op == Op::Not) d = depth[g.in0];
      if (g.op == Op::And) ++d;
      depth[g.out] = d; max_depth = std::max(max_depth, d);
    }
    std::vector<std::vector<size_t>> nonlinear(max_depth + 1), linear(max_depth + 1);
    for (size_t j = 0; j < program.gates.size(); ++j) {
      const auto &g = program.gates[j];
      (g.op == circuit::Op::And ? nonlinear : linear)[depth[g.out]].push_back(j);
    }
    Shares wires(program.num_wires);
    std::copy(inputs.begin(), inputs.end(), wires.begin());
    const auto one = public_bit(true);
    for (uint32_t d = 0; d <= max_depth; ++d) {
      Shares a, b; a.reserve(nonlinear[d].size()); b.reserve(nonlinear[d].size());
      for (size_t j : nonlinear[d]) {
        const auto &g = program.gates[j]; a.push_back(wires[g.in0]); b.push_back(wires[g.in1]);
      }
      auto products = and_batch(a, b);
      for (size_t j = 0; j < products.size(); ++j)
        wires[program.gates[nonlinear[d][j]].out] = products[j];
      for (size_t j : linear[d]) {
        const auto &g = program.gates[j];
        using circuit::Op;
        if (g.op == Op::Xor) wires[g.out] = wrk::xor_share(wires[g.in0], wires[g.in1]);
        else if (g.op == Op::Not) wires[g.out] = wrk::xor_share(wires[g.in0], one);
        else wires[g.out] = g.op == Op::Const1 ? one : Share{};
      }
    }
    last_and_depth = max_depth;
    Shares outputs; outputs.reserve(program.outputs.size());
    for (uint32_t w : program.outputs) outputs.push_back(wires[w]);
    return outputs;
  }

  // Complete ALL malicious-COT checks and close those sessions explicitly.
  // Call before persisting online snapshots. No later operation is permitted.
  void finish() {
    active();
    if (fkos_) fkos_->finish();
    triples_.abit.finish();
    (void)open({}, "GMW-finish-ready");
    finished_ = true;
    bank_.clear(); bank_.shrink_to_fit(); bank_pos_ = 0;
  }

  const ag::FkosTriples<N> *fkos_metrics() const { return fkos_.get(); }

#ifdef EMP_AG_LOCAL_TEST_HOOKS
  Shares test_triple_values() const {
    Shares out; out.reserve(3 * bank_.size());
    for (const auto &t : bank_) { out.push_back(t.a); out.push_back(t.b); out.push_back(t.c); }
    return out;
  }
  void test_corrupt_native_open(const std::string &stage) {
    triples_.local_open_test_hook = [this, stage](const char *current,
        unsigned char *bits, size_t count) {
      if (party == 2 && stage == current && count) bits[0] ^= 1;
    };
  }
  void test_corrupt_fkos(const std::string &stage) {
    wrk::require(fkos_ != nullptr, "FKOS test hook requires FKOS backend");
    fkos_->local_test_hook = [this, stage](const char *current, uint8_t *bits, size_t count) {
      if (party != 2 || stage != current || !count) return;
      if (stage == "all-products") for (size_t i = 0; i < count; ++i) bits[i] ^= 1;
      else bits[0] ^= 1;
    };
  }
#endif

 private:
  using Triple = ag::BooleanTriple<N>;
  NetIOMP<N> *io_;
  ThreadPool *pool_;
  ag::TriplePool<N> triples_;
  std::unique_ptr<ag::FkosTriples<N>> fkos_;
  std::vector<Triple> bank_;
  size_t bank_pos_ = 0;
  bool finished_ = false;
  bool failed_ = false;
  void active() const {
    wrk::require(!finished_ && !failed_, "GMW session finished or aborted; use fresh material");
  }

  static Share export_share(const ag::AShareBundle<N> &s) {
    Share out{}; out.bit = ag::own_bit(s);
    for (int j = 0; j < N - 1; ++j) { out.mac(j) = s.mac(j); out.key(j) = s.key(j); }
    return out;
  }

  void mint_triples(int length) {
    if (fkos_) {
      auto generated = fkos_->generate(length);
      bank_.insert(bank_.end(), std::make_move_iterator(generated.begin()),
                   std::make_move_iterator(generated.end()));
      triples_generated += length;
      random_bits_generated += 2 * static_cast<uint64_t>(length);
      return;
    }
    ag::AShareBundleVec<N> native, products;
    triples_.abit.draw(2 * length, native);
    triples_.prepare_beaver_acc(length);
    std::vector<unsigned char> a(length), b(length);
    for (int j = 0; j < length; ++j) {
      a[j] = ag::own_bit(native[j]); b[j] = ag::own_bit(native[length + j]);
      for (int peer = 1; peer <= N; ++peer) if (peer != party) {
        const int slot = ag::peer_slot(party, peer);
        triples_.bkt_accMAC_[peer][j] = native[j].mac(slot);
        triples_.bkt_accKEY_[peer][j] = native[j].key(slot);
        triples_.bkt_accMAC_[peer][length + j] = native[length + j].mac(slot);
        triples_.bkt_accKEY_[peer][length + j] = native[length + j].key(slot);
      }
    }
    triples_.compute_inplace(a.data(), b.data(), length, products);
    triples_.abit.maybe_flush_cot_check();
    for (int j = 0; j < length; ++j)
      bank_.push_back({export_share(native[j]), export_share(native[length + j]), export_share(products[j])});
    triples_generated += length;
    random_bits_generated += 2 * static_cast<uint64_t>(length);
  }
};
}  // namespace emp::gmw
